import itertools

# Total number of attributes per card
num_shapes = 3
num_colors = 3
num_shades = 3

# We need to generate all possible sets of three cards and check if they meet the criteria
def is_complementary(set_of_cards):
    shapes = set(card[0] for card in set_of_cards)
    color = set(card[1] for card in set_of_cards)
    shade = set(card[2] for card in set_of_cards)

    if (len(shapes) == 1):
        for shape in shapes:
            if not (shape in card[0] for card in set_of_cards):
                return False
    else:
        if len(shapes) == 3:
            for shape in shapes:
                if not (shape in card[0] for card in set_of_cards):
                    return False
    if (len(color) == 1):
        for color in color:
            if not (color in card[1] for card in set_of_cards):
                return False
    else:
        if len(color) == 3:
            for color in color:
                if not (color in card[1] for card in set_of_cards):
                    return False
    if (len(shade) == 1):
        for shade in shade:
            if not (shade in card[2] for card in set_of_cards):
                return False
    else:
        if len(shade) == 3:
            for shade in shade:
                if not (shade in card[2] for card in set_of_cards):
                    return False
    return True

# Generate all 27 cards
cards = [(shape, color, shade) for shape in range(num_shapes) for color in range(num_colors) for shade in range(num_shades)]

# Find all 3-card subsets that are complementary
complementary_sets = []
for subset in itertools.combinations(cards, 3):
